    events = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": events}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 3)])
def test_campaign_summary_pooled_rounded_rate_and_calendar_window(days, recent):
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [
            {"day": 1, "converted": True},
            {"day": 2, "converted": False},
            {"day": 4, "converted": True},
            {"day": 5, "converted": None},
            {"day": 5, "converted": False},
            {"day": 5, "converted": False},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.429, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]), (10, ["best", "a", "z", "worst"])])
def test_top_converting_groups_sort_ties_and_exclude_empty(n, expected):
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "empty": [],
        "worst": [{"converted": False}],
        "a": [{"converted": True}, {"converted": False}],
        "best": [{"converted": True}],
    }
    assert top_converting_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_converting_groups_no_sessions(groups):
    assert top_converting_groups(groups, 3) == []
